import * as React from "react"

import { cn } from "@/lib/utils"

type ItemGroupProps = React.ComponentProps<"ul"> & {
  /**
   * leader: a dotted leader joins what it is to its value. lineation: as in a critical edition, every
   * fifth line carries its number in the margin, and the line you point at shows its own. words: the
   * description runs in along the leader, small, and runs out in an ellipsis before the value.
   */
  variant?: "leader" | "lineation" | "words"
}

/** A ledger of items. */
function ItemGroup({ className, variant = "leader", ...props }: ItemGroupProps) {
  return <ul data-slot="item-group" data-variant={variant === "leader" ? undefined : variant} className={cn("ot-items", className)} {...props} />
}

type ItemProps = React.ComponentProps<"li"> & {
  /** Pins a state for documentation ("hover"); set on the root. */
  "data-force"?: string
}

/** A ledger line: what it is, a dotted leader, what you can do. Point at it and the leader inks across. */
function Item({ className, ...props }: ItemProps) {
  return <li data-slot="item" className={cn("ot-item", className)} {...props} />
}

/** An avatar or other small picture at the start of the line. */
function ItemMedia({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="item-media" className={cn("ot-item-media", className)} {...props} />
}

function ItemContent({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="item-content" className={cn("ot-item-body", className)} {...props} />
}

function ItemTitle({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="item-title" className={cn("ot-item-title", className)} {...props} />
}

function ItemDescription({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="item-description" className={cn("ot-item-desc", className)} {...props} />
}

/** A value or an action at the end of the line, joined to the content by the leader. */
function ItemActions({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <>
      <span data-slot="item-leader" className="ot-item-leader" aria-hidden="true" />
      <span data-slot="item-actions" className={cn("ot-item-end", className)} {...props} />
    </>
  )
}

export { ItemGroup, Item, ItemMedia, ItemContent, ItemTitle, ItemDescription, ItemActions }

@layer components {
  /* ── ot-item ── a ledger line: what it is, a dotted leader, what you can do. As on a contents page, the dots sit on the
     baseline the title and the value share. */
  .ot-items { list-style: none; margin: 0; padding: 0; border-top: var(--ot-hairline) solid var(--ot-rule); }
  .ot-item { display: flex; align-items: baseline; gap: var(--ot-space-4); padding-block: var(--ot-space-4); border-bottom: var(--ot-hairline) solid var(--ot-rule); }
  .ot-item-media { flex: none; display: inline-flex; align-self: center; }
  .ot-item-body { display: grid; min-width: 0; }
  .ot-item-title { color: var(--ot-ink); }
  .ot-item-desc { font-size: var(--ot-pp); line-height: var(--ot-pp-lh); color: var(--ot-pencil); }
  .ot-item-end { font-variant-numeric: tabular-nums; color: var(--ot-ink); }
  .ot-item-leader { position: relative; flex: 1; min-width: var(--ot-space-5); height: 2px; }
  .ot-item-leader::before, .ot-item-leader::after { content: ""; position: absolute; inset: 0; background: radial-gradient(circle, currentColor 0.8px, transparent 1.1px) 0 50% / 6px 2px repeat-x; }
  .ot-item-leader::before { color: var(--ot-rule-strong); }
  .ot-item-leader::after {
    color: var(--ot-ink);
    mask: linear-gradient(#000, #000) no-repeat 100% 0 / 0% 100%;
    transition: mask-size var(--ot-andante) var(--ot-exhale), mask-position 0s;
  }
  .ot-item:is(:hover, :focus-within, [data-force~="hover"]) .ot-item-leader::after { mask-position: 0 0; mask-size: 100% 100%; }

  /* ── lineation ── a critical edition's line numbers: every fifth line carries its number in the margin, in pencil; the line
     you point at or focus shows its own, in ink. The figure hangs into the margin and steps in where the margin is too narrow. */
  .ot-items[data-variant="lineation"] { counter-reset: ot-line; }
  .ot-items[data-variant="lineation"] > .ot-item { counter-increment: ot-line; }
  .ot-items[data-variant="lineation"] > .ot-item::before {
    content: ""; order: -1; flex: none; width: 2em; margin-inline-start: calc(-2em - var(--ot-space-4)); text-align: end;
    font-size: var(--ot-pp); line-height: var(--ot-pp-lh); font-variant-numeric: tabular-nums; color: var(--ot-pencil); transition: color var(--ot-allegro);
  }
  .ot-items[data-variant="lineation"] > .ot-item:nth-child(5n)::before { content: counter(ot-line) / ""; }
  .ot-items[data-variant="lineation"] > .ot-item:is(:hover, :focus-within, [data-force~="hover"])::before { content: counter(ot-line) / ""; color: var(--ot-ink); }
  @media (max-width: 40rem) { .ot-items[data-variant="lineation"] > .ot-item::before { margin-inline-start: 0; } }

  /* ── words ── SPECTRA's small print run along a contents line: the description runs in after the title, small, where the
     dots would be, and runs out in an ellipsis before the value; a short one leaves the dots to finish the line. Pointing inks it
     with its leader. */
  .ot-items[data-variant="words"] { min-width: 0; } /* the unbroken sentences mustn't widen whatever holds the list */
  .ot-items[data-variant="words"] .ot-item-body { display: contents; }
  .ot-items[data-variant="words"] .ot-item-leader { flex-basis: 0; min-width: 0; } /* only what the words leave; none when they run out */
  .ot-items[data-variant="words"] .ot-item-title { flex: none; }
  .ot-items[data-variant="words"] .ot-item-desc { flex: 0 1 auto; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; transition: color var(--ot-allegro); }
  .ot-items[data-variant="words"] .ot-item:is(:hover, :focus-within, [data-force~="hover"]) .ot-item-desc { color: var(--ot-graphite); }
}
